const crypto = require('crypto');

const rawBody = JSON.stringify($json.body);
const signature = $json.headers['x-lendloop-signature'];
const secret = $env.LENDLOOP_WEBHOOK_SECRET;

if (!signature || !secret) {
  throw new Error('HMAC signature or environment secret missing');
}

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

// Timing-safe comparison
const sigBuf = Buffer.from(signature, 'utf8');
const expBuf = Buffer.from(expected, 'utf8');

if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Invalid HMAC signature verification');
}

return {
  json: {
    verified: true,
    event: $json.headers['x-lendloop-event'],
    ...$json.body
  }
};

console.log(`[LendLoop Notification] New tool request for '${$json.toolName}' from ${$json.startDate} to ${$json.endDate}. User ID notified: ${$json.targetUserId}`);
return {
  json: {
    notified: true,
    channel: 'log_mock',
    recipient: $json.targetUserId,
    message: `A neighbor requested to borrow ${$json.toolName}`
  }
};

console.log(`[LendLoop Notification] Tool request for '${$json.toolName}' was updated to status: ${$json.status}. User ID notified: ${$json.targetUserId}`);
return {
  json: {
    notified: true,
    channel: 'log_mock',
    recipient: $json.targetUserId,
    message: `Your request for ${$json.toolName} was ${$json.status}`
  }
};
